// Package each email for VendorIQ: sender, subject, text, SPF/DKIM result, attachments (base64) and an
// 'automated' flag (newsletters, bounces, auto-replies) so the app never answers machines.
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const j = item.json;
  const attachments = [];
  for (const key of Object.keys(item.binary || {})) {
    const meta = item.binary[key];
    const buf = await this.helpers.getBinaryDataBuffer(i, key);
    attachments.push({ name: meta.fileName || key, mime: meta.mimeType, b64: buf.toString('base64') });
  }
  const h = j.headers || {};
  const header = (k) => String(h[k] || '').replace(new RegExp('^' + k + ':\\s*', 'i'), '');
  const automated = !!header('list-unsubscribe') || /^(auto-generated|auto-replied)/i.test(header('auto-submitted')) || /bulk|list|junk/i.test(header('precedence'));
  const from = (j.from && (j.from.text || (j.from.value && j.from.value[0] && j.from.value[0].address))) || '';
  out.push({ json: { gmail_id: j.id, from, subject: j.subject || '', text: j.text || '', message_id: j.messageId || j.id, auth: header('authentication-results'), automated, attachments } });
}
return out;
